Handle: func(s string, n contentNodeI, match doctree.DimensionFlag) (bool, error) {
	p := n.(*pageState)
	if p.File() != nil && !p.File().IsContentAdapter() {
		add(p.File().FileInfo().Meta().PathInfo.BaseNameNoIdentifier(), p)
	} else if p.PathInfo() != nil {
		// Pages created by a content adapter are all backed by the same
		// content adapter file, so use the page's own path.
		add(p.PathInfo().BaseNameNoIdentifier(), p)
	}
	return false, nil
},

